func And(predicates ...predicate.ToolAgentOverride) predicate.ToolAgentOverride {
	return predicate.ToolAgentOverride(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ToolAgentOverride) predicate.ToolAgentOverride {
	return predicate.ToolAgentOverride(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ToolAgentOverride) predicate.ToolAgentOverride {
	return predicate.ToolAgentOverride(sql.NotPredicates(p))
}
